// BEFORE — drilling
function Layout({ posts, user, theme }) {
  return (
    <div className={theme}>
      <Header user={user} />
      <Sidebar user={user} />
      <Content posts={posts} />
    </div>
  );
}

// AFTER — composition
function Layout({ children, theme }) {
  return <div className={theme}>{children}</div>;
}

// App.js
<Layout theme={theme}>
  <Header user={user} />
  <Sidebar user={user} />
  <Content posts={posts} />
</Layout>
